const params = new URLSearchParams(location.search);
const pages = {home:'首页',list:'任务',form:'新建需求',detail:'任务详情',settings:'设置'};
let currentPage = pages[params.get('page')] ? params.get('page') : 'home';
let mockUnknown = false, mockDirty = false, dialogTrigger = null, noticeTimer = null, pendingMockDestination = null;
let currentSettingsGroup='模型与会话';
const mockSettingsDrafts=new Map();
const mockFilters={project:'全部项目',archive:'未归档',order:'最近更新'};
const dialog = document.querySelector('#preview-dialog'), main = document.querySelector('main'), skin = document.querySelector('#skin');
skin.value = ['spdb','tech-blue','github-white'].includes(params.get('skin')) ? params.get('skin') : 'github-white';
document.documentElement.dataset.skin = skin.value;
const navGroups = [
  {label:'工作',items:[['⌂','首页','home'],['◎','任务','list'],['⑂','需求任务','form'],['▤','待处理中心','detail']]},
  {label:'创作与资料',items:[['▱','项目','项目'],['⌘','流程','流程'],['▧','PPT 制作','PPT 制作'],['▥','知识库','知识库'],['▦','模板任务','模板任务']]},
  {label:'管理',fold:true,items:[['◷','历史设计','历史设计'],['▥','质量与用量','质量与用量'],['⌁','运行环境','运行环境'],['⚒','工具与 Skill','工具与 Skill'],['▱','数据库','数据库'],['♧','角色管理','角色管理'],['⚙','设置','settings']]},
];
function navHtml(){return navGroups.map(g=>`${g.fold?'<details><summary>管理与设置</summary>':`<div class="nav-group">${g.label}</div>`}${g.items.map(([glyph,label,page])=>`<a class="nav-item ${page===currentPage?'active':''}" href="?page=${pages[page]?page:currentPage}" ${pages[page]?`data-page="${page}"`:`data-destination="${label}"`} ${page===currentPage?'aria-current="page"':''}><span class="nav-glyph" aria-hidden="true">${glyph}</span>${label}${label==='待处理中心'?'<span class="count badge warning">2</span>':''}</a>`).join('')}${g.fold?'</details>':''}`).join('');}
const primary=(text,attrs='')=>`<button class="button primary" ${attrs}>${text}</button>`;
const button=(text,attrs='')=>`<button class="button" ${attrs}>${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const pageTitle=(title,subtitle,actions='')=>`<div class="page-title"><div><span class="eyebrow">${currentPage==='detail'?'示例项目 / 任务':'工作区'}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const tasks=[['为订单服务补充退款能力','等待回答','warning','订单服务','刚刚'],['完善新用户引导','执行中','running','控制台','8 分钟前'],['修复导出文件格式','可恢复失败','warning','报表服务','24 分钟前'],['整理接口文档','已完成','success','订单服务','1 小时前'],['补充回归验证','等待开始','','控制台','2 小时前'],['更新项目说明','已完成','success','报表服务','昨天']];
function home(){return `<section class="hero"><span class="eyebrow">从这里继续</span><h1>把想法推进到交付。</h1><p>规划下一步，也照看正在进行的工作。</p><div class="actions">${primary('＋ 新增需求','data-page="form"')}${button('查看任务 →','data-page="list"')}</div></section><section class="metrics" aria-label="模拟工作概况"><div class="metric"><strong>3</strong><span>正在推进</span><small>模拟任务状态</small></div><div class="metric"><strong>2</strong><span>需要你决定</span><small>问题与恢复入口</small></div><div class="metric"><strong>8</strong><span>近期完成</span><small>模拟最近七天</small></div></section><div class="home-grid"><section><div class="section-heading"><h2>现在需要你</h2><a href="?page=detail" data-page="detail">全部待处理 →</a></div><div class="panel"><div class="row"><div><h3>退款失败时的补偿方式</h3><small>订单服务 · 为订单服务补充退款能力</small></div>${button('回答问题','data-page="detail"')}</div><div class="row"><div><h3>导出格式需要恢复处理</h3><small>报表服务 · 保留原任务与版本</small></div>${button('查看恢复','data-open="recovery"')}</div></div><div class="section-heading" style="margin-top:28px"><h2>最近任务</h2><a href="?page=list" data-page="list">全部任务 →</a></div><div class="panel">${tasks.slice(0,3).map(t=>`<div class="row"><div><h3><a href="?page=detail" data-page="detail" style="color:var(--text)">${t[0]}</a></h3><small>${t[3]} · ${t[4]}</small></div>${badge(t[1],t[2])}</div>`).join('')}</div></section><section><div class="section-heading"><h2>工作项目</h2><a href="#" data-destination="项目">管理 →</a></div><div class="panel panel-pad"><span class="eyebrow">示例项目</span><div class="project-card"><span class="project-icon" aria-hidden="true">▱</span><div><h3>订单服务</h3><small>本地项目 · 模拟内容</small></div></div><p class="small">需求、流程和运行结果归入同一个项目。</p><div class="quick-links" style="margin-top:18px">${button('⑂ 创建需求','data-page="form"')}${button('◎ 查看任务','data-page="list"')}</div></div><div class="section-heading" style="margin-top:28px"><h2>创作与资料</h2></div><div class="quick-links" style="border:0;padding:0">${button('⌘ 流程','data-destination="流程"')}${button('▧ PPT 制作','data-destination="PPT 制作"')}${button('▥ 知识库','data-destination="知识库"')}${button('▦ 模板任务','data-destination="模板任务"')}</div></section></div>`;}
function list(){return pageTitle('任务','跟进执行过程，查看结果与下一步。',primary('＋ 新增需求','data-page="form"'))+`<div class="filters"><div class="filters-start"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">搜索任务</span><input id="search" placeholder="搜索任务名称" autocomplete="off"></label><div class="segments" aria-label="任务状态">${['全部','执行中','待处理','已完成'].map((x,i)=>`<button type="button" aria-pressed="${i===0}" data-filter="${x}">${x}</button>`).join('')}</div></div>${button('筛选与排序 ⌄','data-open="filters"')}</div><div class="panel"><table class="table"><thead><tr><th>任务</th><th>状态</th><th class="project-column">项目</th><th>更新于</th><th><span class="sr-only">操作</span></th></tr></thead><tbody id="task-rows">${tasks.map((t,i)=>`<tr data-task="${t[0]}" data-state="${t[1]}"><td class="title-cell"><a href="?page=detail" data-page="detail">${t[0]}</a><small>${i===0?'有一个问题等待你的回答':i===2?'恢复入口保留任务身份':i===4?'确认后才申请执行':'查看过程、制品与评审'}</small></td><td>${badge(t[1],t[2])}</td><td class="project-column">${t[3]}</td><td class="updated-column">${t[4]}</td><td class="row-menu"><button class="icon-button" aria-label="${t[0]}的更多操作" data-open="row" data-row="${i}">⋯</button></td></tr>`).join('')}</tbody></table><div class="table-footer"><span id="result-count">6 项模拟任务</span>${button('加载更多','data-feedback="模拟：当前示例已全部展示"')}</div></div><p class="small" style="margin-top:15px">恢复与待回答事项保持可见；归档、设计历史等操作位于每行“更多”。</p>`;}
function form(){return pageTitle('新建需求','先写清目标，再进入画布安排工作。',button('返回需求列表','data-destination="需求任务"'))+`<div class="form-layout"><form id="requirement-form" class="panel form-card"><label class="field"><span>需求名称</span><input name="title" maxlength="120" value="为订单服务补充退款能力" required></label><label class="field"><span>需求说明</span><textarea name="objective" required>支持订单退款，保留退款记录与可追踪的失败原因。&#10;&#10;约束：保持现有支付协议；先完成设计与验证，再开始执行。&#10;交付：实现方案、必要测试与可审查的结果。</textarea><small>说明目标、约束和希望得到的交付物。</small></label><section class="form-section"><h2>工作方式</h2><div class="fields-two"><label class="field"><span>工作项目</span><select name="project"><option>订单服务（示例）</option><option>控制台（示例）</option></select></label><label class="field"><span>使用流程</span><select name="flow"><option>标准开发流程（示例）</option><option>轻量开发流程（示例）</option></select></label></div><details class="disclosure"><summary>查看流程版本与保存约定</summary><p>模拟版本 3 · 本次需求独立保存。进入规划后仍可调整节点，确认计划后才开始执行。</p></details></section><div id="form-receipt"></div><footer class="form-footer"><small id="draft-state">模拟草稿 · 尚未提交</small>${primary('进入规划画布 →','type="submit"')}</footer></form><aside class="guidance"><h3>从需求到交付</h3><ol><li>写下目标与约束<br><small>选择项目和可复用流程。</small></li><li>在画布中整理计划<br><small>按选中节点查看相关操作。</small></li><li>确认之后开始执行<br><small>运行状态与结果由服务端确认。</small></li></ol><div class="note">这是一份设计原型，按钮不会创建真实需求。</div></aside></div><div class="actions" style="margin-top:17px">${button('演示未知回执','data-open="unknown"')}</div>`;}
function detail(){return pageTitle('为订单服务补充退款能力','订单服务 · 当前状态：等待回答 · 模拟内容',`${button('更多操作 ⋯','data-open="task-actions"')}${primary('回答问题','data-focus="answer"')}`)+`<section class="alert" role="status"><div><h3>有一个问题等待你回答</h3><p>确认补偿方式后继续推进。历史错误保留在审计中。</p></div>${button('定位问题 ↓','data-focus="answer"')}</section><section class="flow-preview" aria-label="模拟阶段示意，非 React Flow 验收"><div class="flow-heading"><span>阶段 · 2 / 4</span><span>示意图 · 将复用已验收 React 画布</span></div><div class="flow-steps">${[['需求与方案','已完成'],['实施','等待回答'],['验证','尚未开始'],['交付','尚未开始']].map((t,i)=>`${i?'<span class="step-arrow" aria-hidden="true">→</span>':''}<button class="step-node ${i===1?'current':''}" data-feedback="模拟：定位${t[0]}阶段">${i===0?'✓ ':''}${t[0]}<small>${t[1]}</small></button>`).join('')}</div></section><div class="detail-grid"><section><div class="panel panel-pad question" id="answer" tabindex="-1"><span class="eyebrow">待回答问题 · 模拟</span><h3>退款失败后，应怎样补偿？</h3><p>请选择策略。回答会保留在当前任务上下文。</p><label class="choice"><input type="radio" name="answer" checked value="人工确认"><span>先保留记录，等待人工确认</span></label><label class="choice"><input type="radio" name="answer" value="同身份重试"><span>依照现有协议，以相同身份恢复</span></label><div class="question-footer"><small>模拟回答，不会提交命令</small>${primary('提交回答','data-feedback="模拟：回答已记录在原型中，无业务请求"')}</div></div><h2 class="log-title">运行输出 <small>模拟摘录</small></h2><div class="log"><span>✓</span> 已读取当前需求与项目约束<br><span>✓</span> 已保留设计版本与任务身份<br>  等待用户确认退款补偿方式<br>  问题回答完成后，由权威状态决定下一步</div><details class="disclosure"><summary>查看历史审计与会话细节</summary><p>模拟：先前检查、提问和设计记录。历史记录不等于当前故障。</p></details></section><aside class="panel panel-pad summary"><h2>任务摘要</h2><dl><dt>工作项目</dt><dd>订单服务</dd><dt>任务方式</dt><dd>标准开发流程</dd><dt>当前阶段</dt><dd>实施</dd><dt>执行次数</dt><dd>1 / 3（模拟）</dd><dt>结果制品</dt><dd>尚未发布</dd></dl>${button('查看设计历史','data-destination="设计历史"')}${button('制品与验收记录','data-destination="制品与验收"')}<details class="disclosure"><summary>恢复与停止</summary><p>根据权威状态展示允许的恢复动作。原型保留入口，不代表当前状态可直接重试或执行。</p>${button('查看恢复方案','data-open="recovery"')}${button('取消任务…','data-open="stop"')}</details></aside></div><div class="actions" style="margin-top:17px">${button('演示冲突解决稿 409（独立模拟）','data-open="conflict"')}</div>`;}
const settingsGroups=['基本配置','模型与会话','执行限制','重试等待','发布','演示数据'];
function settingsFields(group='模型与会话'){if(group==='模型与会话')return `<h2>模型与会话</h2><p class="settings-description">默认配置的归属与生效范围明确，页面不改写运行中的模型。</p><h3 class="settings-subheading">连接方式 ${badge('重启生效')}</h3><div class="fields-two"><label class="field"><span>连接方式</span><select><option>自动发现（兼容）</option><option>固定地址</option></select></label><label class="field"><span>服务地址</span><input value="http://localhost:4096" aria-describedby="mock-address"></label></div><p id="mock-address" class="small">示例本地地址，不会发起连接。</p><hr class="separator"><h3 class="settings-subheading">默认模型 ${badge('新会话生效')}</h3><div class="fields-two"><label class="field"><span>模型提供方</span><select><option>示例提供方</option></select></label><label class="field"><span>模型</span><select><option>示例模型 · 未调用</option></select></label></div><details class="disclosure"><summary>连接与启动超时</summary><div class="fields-two"><label class="field"><span>连接超时（秒）</span><input type="number" value="30" min="1" max="120"></label><label class="field"><span>启动超时（秒）</span><input type="number" value="120" min="1" max="300"></label></div><label class="field"><span>请求超时（秒）</span><input type="number" value="300" min="1" max="600"></label></details>`;if(group==='执行限制')return `<h2>执行限制</h2><p class="settings-description">模拟字段，新任务生效；已有任务保持原设置。</p><div class="switch-line"><span>启用业务超时限制</span><button class="switch" role="switch" aria-checked="false" aria-label="启用业务超时限制"></button></div><div class="fields-two"><label class="field"><span>单阶段最大尝试次数</span><input type="number" min="1" max="20" value="3"></label><label class="field"><span>模板分析并发数</span><input type="number" value="2"></label></div>`;return `<h2>${group}</h2><p class="settings-description">${group}的模拟信息结构。正式字段与权限以完整功能清单和原 DTO 为准。</p><div class="panel-confirm">本组在原型中仅展示入口，不提供真实配置或操作。</div>${button('查看本组完整迁移清单','data-feedback="模拟：完整字段与动作见 core-ui-inventory.md"')}`;}
function settings(){return pageTitle('设置','按任务分组配置，保留输入与明确的生效范围。',`${button('恢复当前基线','data-open="reset"')}${primary('保存设置','data-feedback="模拟：保存成功示例，无业务请求"')}`)+`<div class="settings-layout"><nav class="settings-nav" aria-label="设置分组">${settingsGroups.map(g=>`<button data-setting="${g}" aria-current="${g==='模型与会话'}">${g}</button>`).join('')}</nav><form class="panel form-card" id="settings-form"><div id="settings-fields">${settingsFields()}</div><div class="form-footer"><small>模拟配置 · 尚未保存</small><span class="small">原设置保存协议，不新增版本字段</span></div></form></div>`;}
function render(focus=false){main.innerHTML=({home,list,form,detail,settings})[currentPage]();document.querySelector('#navigation').innerHTML=navHtml();document.querySelector('#breadcrumb').textContent=pages[currentPage];if(currentPage==='settings'){currentSettingsGroup='模型与会话';restoreMockSettings();document.querySelector('#navigation details').open=true;}if(focus)main.focus();}
function applyListFilters(){const query=document.querySelector('#search')?.value||'',status=document.querySelector('[data-filter][aria-pressed="true"]')?.dataset.filter||'全部';let count=0;document.querySelectorAll('[data-task]').forEach(row=>{const project=row.querySelector('.project-column').textContent;row.hidden=!row.dataset.task.includes(query)||(status!=='全部'&&!({'执行中':['执行中'],'待处理':['等待回答','可恢复失败','等待开始'],'已完成':['已完成']}[status]||[]).includes(row.dataset.state))||(mockFilters.project!=='全部项目'&&project!==mockFilters.project)||mockFilters.archive==='已归档';if(!row.hidden)count++;});document.querySelector('#result-count').textContent=`${count} 项模拟任务`;const rows=[...document.querySelectorAll('[data-task]')];rows.sort((a,b)=>(tasks.findIndex(t=>t[0]===a.dataset.task)-tasks.findIndex(t=>t[0]===b.dataset.task))*(mockFilters.order==='最早更新'?-1:1));rows.forEach(r=>document.querySelector('#task-rows').append(r));}
function saveMockSettings(){const host=document.querySelector('#settings-fields');mockSettingsDrafts.set(currentSettingsGroup,{fields:[...host.querySelectorAll('input,select')].map(x=>x.value),details:[...host.querySelectorAll('details')].map(x=>x.open),switches:[...host.querySelectorAll('[role="switch"]')].map(x=>x.getAttribute('aria-checked'))});}
function restoreMockSettings(){const saved=mockSettingsDrafts.get(currentSettingsGroup);if(!saved)return;const host=document.querySelector('#settings-fields');host.querySelectorAll('input,select').forEach((x,i)=>x.value=saved.fields[i]);host.querySelectorAll('details').forEach((x,i)=>x.open=saved.details[i]);host.querySelectorAll('[role="switch"]').forEach((x,i)=>x.setAttribute('aria-checked',saved.switches[i]));}
function feedback(message){const n=document.querySelector('#notice');n.textContent=message;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,4500);}
function openPanel(kind,trigger,label,row){if(!dialog.open)dialogTrigger=trigger;let title='',body='';
  if(kind==='navigation'){title='导航';body=`<nav aria-label="移动主导航">${navHtml()}</nav>`;}
  else if(kind==='filters'){title='筛选与排序';body=`<p>模拟筛选面板，关闭后返回原入口。</p><label class="field"><span>工作项目</span><select><option>全部项目</option><option>订单服务</option><option>控制台</option></select></label><label class="field"><span>归档范围</span><select><option>未归档</option><option>已归档</option><option>全部</option></select></label><label class="field"><span>排序</span><select><option>最近更新</option><option>最早更新</option></select></label><div class="dialog-actions">${button('取消','data-close')}${primary('应用筛选','data-apply')}</div>`;}
  else if(kind==='row'){title='任务操作';const index=Number(row);body=`<p>${tasks[index][0]} · 模拟状态</p><div class="menu-actions">${button('打开任务','data-page="detail"')}${index===2?button('恢复任务','data-open="recovery"'):''}${button('查看设计历史','data-destination="设计历史"')}${button('归档任务…','data-feedback="模拟：正式归档需按权限与状态确认"')}</div><p style="margin-top:20px">只有已归档且允许删除的普通任务才显示永久删除；本示例未归档。</p>`;}
  else if(kind==='unknown'){mockUnknown=true;const receipt=document.querySelector('#form-receipt');if(receipt)receipt.innerHTML=`<section class="alert" style="margin-top:18px" role="status"><div><h3>提交结果尚未确认（模拟）</h3><p>保留草稿与原请求身份，先查询回执。</p></div></section>`;title='结果尚未确认';body=`<div class="panel-confirm">模拟 unknown 状态：不离开，不新建请求。这里演示建议的导航保护，尚未接入真实协议。</div><p>原名称、说明与选择保持在当前原型内存；没有真实 File 或已接受命令。</p><div class="dialog-actions">${button('留在当前页','data-close')}${primary('查询原回执（模拟）','data-resolve')}</div>`;}
  else if(kind==='dirty'){title='保留当前草稿？';body=`<p>模拟未提交修改：留在当前页继续编辑，或明确放弃本原型草稿。这不能用于放弃未知写入。</p><div class="dialog-actions">${button('继续编辑','data-close autofocus')}${button('放弃模拟草稿并离开','data-discard')}</div>`;}
  else if(kind==='conflict'){title='冲突解决稿版本已变化';body=`<div class="panel-confirm">独立模拟 local-sync resolution 409：远端版本 8，本地基线 7。不代表当前等待回答任务具备发布权限。</div><label class="field"><span>保留的解决稿（模拟）</span><textarea id="conflict-draft">保留现有退款失败记录，由人工确认后处理。</textarea></label><p>保留解决稿与原版本，先读取冲突内容，不自动覆盖或重复写入。</p><div class="menu-actions">${button('保留草稿并查看差异','data-feedback="模拟：差异审阅入口，尚未实现字段合并"')}${button('留在当前页','data-close')}</div>`;}
  else if(kind==='recovery'){title='恢复方案';body=`<p>模拟恢复入口。保留原任务身份、冻结设计和版本，先读取权威状态。</p><div class="panel-confirm">停止证明、未知回执和版本冲突不会被视觉简化跳过。</div>${button('关闭并保留当前状态','data-close')}`;}
  else if(kind==='stop'||kind==='reset'){title=kind==='stop'?'取消任务':'恢复当前基线';body=`<p>模拟危险操作确认。正式执行必须通过现有权限、回执与版本保护。</p><div class="dialog-actions">${button('取消','data-close autofocus')}${button('确认（仅模拟）','data-confirm')}</div>`;}
  else if(kind==='task-actions'){title='当前任务操作';body=`<div class="menu-actions">${button('设计历史','data-destination="设计历史"')}${button('恢复方案','data-open="recovery"')}${button('取消任务…','data-open="stop"')}</div><p style="margin-top:18px">本模拟状态为等待回答，不显示开始执行、继续一轮或重试评审；正式可用性由服务端投影决定。</p>`;}
  else{title=label||kind;body=`<p>${title}入口保留。当前原型只实现五类代表页，其他功能入口仅供信息架构审查。</p><div class="panel-confirm">完整动作、权限与恢复合同见专题报告；这不是已迁移页面。</div>${button('关闭预览','data-close')}`;}
  document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=body;if(kind==='filters')dialog.querySelectorAll('select').forEach((x,i)=>x.value=mockFilters[['project','archive','order'][i]]);if(!dialog.open)dialog.showModal();const first=dialog.querySelector('[autofocus]')||dialog.querySelector('[data-close]');first?.focus();
}
function closePanel(){dialog.close();}
dialog.addEventListener('close',()=>{const returnTo=dialogTrigger;dialogTrigger=null;if(returnTo?.isConnected)returnTo.focus();});
// Own only this prototype dialog's keyboard boundary; no production/global listener manipulation.
dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(e=>e.getClientRects().length>0);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}});
document.addEventListener('click',event=>{
  const t=event.target.closest('button,a');if(!t)return;
  if(t.dataset.page){event.preventDefault();if(mockUnknown){openPanel('unknown',t);return;}if(mockDirty&&currentPage==='form'){pendingMockDestination=t.dataset.page;openPanel('dirty',t);return;}if(dialog.open)closePanel();currentPage=t.dataset.page;mockDirty=false;render(true);return;}
  if(t.dataset.destination){event.preventDefault();openPanel(t.dataset.destination,t,t.dataset.destination);return;}
  if(t.dataset.open){event.preventDefault();openPanel(t.dataset.open,t,undefined,t.dataset.row);return;}
  if(t.hasAttribute('data-close')){closePanel();return;}
  if(t.hasAttribute('data-apply')){dialog.querySelectorAll('select').forEach((x,i)=>mockFilters[['project','archive','order'][i]]=x.value);closePanel();applyListFilters();feedback('模拟：筛选已用于当前六行示例，无数据请求');return;}
  if(t.hasAttribute('data-discard')){if(mockUnknown)return;mockDirty=false;closePanel();currentPage=pendingMockDestination||'list';pendingMockDestination=null;render(true);return;}
  if(t.hasAttribute('data-confirm')){closePanel();feedback('模拟：确认反馈，无业务请求');return;}
  if(t.hasAttribute('data-resolve')){mockUnknown=false;closePanel();feedback('模拟：原回执查询返回尚未接受；草稿保留，未重新提交');const receipt=document.querySelector('#form-receipt');if(receipt)receipt.innerHTML='';return;}
  if(t.dataset.feedback){feedback(t.dataset.feedback);return;}
  if(t.dataset.focus){document.querySelector(`#${t.dataset.focus}`)?.focus();return;}
  if(t.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===t)));applyListFilters();return;}
  if(t.dataset.setting){saveMockSettings();currentSettingsGroup=t.dataset.setting;document.querySelectorAll('[data-setting]').forEach(x=>x.setAttribute('aria-current',String(x===t)));document.querySelector('#settings-fields').innerHTML=settingsFields(t.dataset.setting);restoreMockSettings();return;}
  if(t.matches('.switch'))t.setAttribute('aria-checked',String(t.getAttribute('aria-checked')!=='true'));
});
document.addEventListener('input',event=>{if(event.target.id==='search')applyListFilters();if(event.target.closest('#requirement-form')){mockDirty=true;document.querySelector('#draft-state').textContent='模拟草稿 · 有未提交修改';}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='requirement-form')openPanel('unknown',event.submitter);});
skin.addEventListener('change',()=>document.documentElement.dataset.skin=skin.value);
window.addEventListener('pagehide',()=>clearTimeout(noticeTimer));
render();
